function fewestGeneEdits(start: string, end: string, bank: string[]): number {
  if (start === end) return 0;
  const oneApart = (x: string, y: string) => {
    let d = 0;
    for (let i = 0; i < 8; i++) if (x[i] !== y[i] && ++d > 1) return false;
    return d === 1;
  };
  const used = new Array(bank.length).fill(false);
  let level = [start], steps = 0;
  while (level.length) {
    steps++;
    const next: string[] = [];
    for (const g of level)
      for (let i = 0; i < bank.length; i++) {
        if (used[i] || !oneApart(g, bank[i])) continue;
        if (bank[i] === end) return steps;
        used[i] = true;
        next.push(bank[i]);
      }
    level = next;
  }
  return -1;
}

