function fewestGeneEdits(start: string, end: string, bank: string[]): number {
  if (start === end) return 0;
  const allowed = new Set(bank);
  if (!allowed.has(end)) return -1;
  const seen = new Set([start]);
  let level = [start], steps = 0;
  while (level.length) {
    steps++;
    const next: string[] = [];
    for (const g of level) {
      for (let i = 0; i < 8; i++) {
        for (const c of "ACGT") {
          if (c === g[i]) continue;
          const h = g.slice(0, i) + c + g.slice(i + 1);
          if (!allowed.has(h) || seen.has(h)) continue;
          if (h === end) return steps;
          seen.add(h);
          next.push(h);
        }
      }
    }
    level = next;
  }
  return -1;
}

