            return 0
        allowed = set(bank)
        if end not in allowed:
            return -1
        seen = {start}
        queue = deque([(start, 0)])
        while queue:
            g, d = queue.popleft()
            for i in range(8):
                for c in "ACGT":
                    if c == g[i]:
                        continue
                    h = g[:i] + c + g[i + 1:]
                    if h in allowed and h not in seen:
                        if h == end:
                            return d + 1
                        seen.add(h)
                        queue.append((h, d + 1))
        return -1

